steps.script:
$ErrorActionPreference='Stop'
$o=@{at=(Get-Date).ToUniversalTime().ToString('o')}
foreach($p in @('ttittulares','ttendencias')){
 $f="C:\TTiTTulares\$p-mobile-trigger.log"
 if(Test-Path $f){$o[$p]=@(Get-Content $f -Tail 60 | Where-Object{$_ -match 'CHAT MESSAGE|LAUNCH|EDITORIAL|ERROR|TIMEOUT'} | Select-Object -Last 12)}
}
$o.runners=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'" | Where-Object{[string]$_.CommandLine -match 'Ejecutar[.]js|TT-Editorial-Guard[.]js'} | ForEach-Object{$_.ProcessId})
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 4))
